     4	final class BellmanFord {
     5	
     6	    private BellmanFord() {}
     7	
     8	    // Delegation shim — preserves the concrete WeightedGraph overload for call sites
     9	    // that were compiled against it, while the algorithm itself works on Graph.
    10	    static ShortestPathResult shortestPaths(WeightedGraph graph, int source) {
    11	        return shortestPaths((Graph) graph, source);
    12	    }
    13	
    14	    static ShortestPathResult shortestPaths(Graph graph, int source) {
    15	        int V = graph.vertices();
    16	        if (source < 0 || source >= V) {
    17	            throw new IllegalArgumentException(
    18	                "Source vertex " + source + " is out of range [0," + (V - 1) + "]");
    19	        }
    20	
    21	        EdgeRelaxer relaxer = new EdgeRelaxer(V, source);
    22	        List<? extends Edge> edges = graph.edges();
    23	
    24	        for (int i = 0; i < V - 1; i++) {
    25	            for (Edge e : edges) {
    26	                relaxer.relax(e);
    27	            }
    28	        }
    29	
    30	        Optional<NegativeCycle> cycle =
    31	            new NegativeCycleDetector(relaxer, edges, V).detect();
    32	
    33	        return cycle.isPresent()
    34	            ? cycle.get()
    35	            : new Distances(source, relaxer.distances(), relaxer.predecessors());
    36	    }
    37	}

